// Only the application shell is cached. Streaming audio and private API responses are excluded.
const CACHE='sonora-shell-v1';
const SHELL=['./','./style.css','./live.css','./offline.css','./live.js','./offline.js','./spotify-weekly.js','./manifest.webmanifest','./icon.svg'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of SHELL){const url=new URL(path,self.registration.scope);const response=await fetch(url,{cache:'reload'});if(!response.ok||response.redirected)throw new Error('Offline asset unavailable');if(path==='./'&&!(await response.clone().text()).includes('name="sonora-offline-shell"'))throw new Error('Unexpected page');await cache.put(url,response)}await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const shellURLs=SHELL.map(path=>new URL(path,self.registration.scope).href);const key=event.request.mode==='navigate'?new URL('./',self.registration.scope).href:url.href;if(!shellURLs.includes(key))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok&&!response.redirected){if(event.request.mode!=='navigate'||(await response.clone().text()).includes('name="sonora-offline-shell"'))await cache.put(key,response.clone())}return response}catch{const cached=await cache.match(key);return cached||Response.error()}})())});
